'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({format:'sq-field-survey',version:1,meshQuantityUnit:'m',project:{name:'農地圍籬勘查',client:'',phone:'',address:'',date:new Date().toLocaleDateString('sv-SE')},conditions:{ground:'一般土壤',access:'小貨車可達',slope:'平坦',demolition:'不需拆除',boundary:'待確認',utilities:'待確認'},notes:'',segments:[seg(20,0),seg(12,90),{...seg(4,0),type:'gate',gate:'double'}],rates:{mesh:180,post:650,rail:100,plate:250,buried:500,direct:0,gate:12000,labor:350},pricing:{extra:0,discount:0,tax:5,excavatorShifts:0,excavatorRate:0,excavatorTransport:0}});
function seg(length=10,turn=0){return{length,turn,type:'fence',height:1.8,spacing:2,wire:3.4,mesh:50,meshChoice:'2英吋',excavator:'待確認',meshMat:'galv',base:'buried',depth:.5,railCount:2,postDia:60.5,gate:'double',angle:0,note:''}}
const meshOptions={'2英吋':50,'3英吋':75,'4英吋':100,'正2英吋':50.8};
function migrate(x){if(x?.format!=='sq-field-survey'||!Array.isArray(x.segments))return x;for(const s of x.segments){s.meshChoice??=Object.keys(meshOptions).find(k=>meshOptions[k]===s.mesh)||('原資料 '+s.mesh+' mm');s.excavator??='待確認'}if(x.rates)x.rates.direct??=0;if(x.pricing){x.pricing.excavatorShifts??=0;x.pricing.excavatorRate??=0;x.pricing.excavatorTransport??=0}x.meshQuantityUnit='m';return x}
let applied=null,appliedSource='',studioLoaded=false;
let data=fresh();try{const x=localStorage.getItem('sq-field-survey-v1');if(x)data=validate(migrate(JSON.parse(x)))}catch{}
function validate(x){if(x?.format!=='sq-field-survey'||x.version!==1||!x.project||!x.conditions||!x.rates||!x.pricing||!Array.isArray(x.segments)||!x.segments.length||x.segments.length>200)throw Error('不是本版勘查資料，或段數超過 200');for(const s of x.segments){for(const [k,a,b]of [['length',.5,5000],['height',.5,6],['spacing',.5,6],['turn',-180,180],['depth',.1,2],['wire',1,6],['mesh',25,150],['railCount',0,4],['postDia',25,200],['angle',0,110]])if(!Number.isFinite(s[k])||s[k]<a||s[k]>b)throw Error(k+' 數值超出範圍');for(const[k,v]of [['type',['fence','gate']],['base',['plate','buried','direct']],['meshMat',['galv','highgalv','pvc']],['gate',['single','double']]])if(!v.includes(s[k]))throw Error('規格選項錯誤')}for(const v of [...Object.values(x.rates),...Object.values(x.pricing)])if(!Number.isFinite(v)||v<0||v>1e7)throw Error('金額設定不正確');for(const k of ['excavatorShifts','excavatorRate','excavatorTransport'])if(!Number.isFinite(x.pricing[k])||x.pricing[k]<0||x.pricing[k]>1e7)throw Error('怪手估價數值不正確');if(x.pricing.excavatorShifts>1000)throw Error('怪手台班數上限1000');if(x.pricing.tax>100||String(x.notes).length>20000)throw Error('資料超出範圍');if(x.segments.reduce((n,s)=>n+s.length,0)>20000)throw Error('本測試版單案總長上限 20,000 公尺');return x}
function field(label,key,value,options,min,max,step){return `<label>${label}${options?`<select data-key="${key}">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:`<input data-key="${key}" value="${esc(value)}" type="${min!==undefined?'number':key==='date'?'date':'text'}" ${min!==undefined?`min="${min}" max="${max}" step="${step||'any'}"`:''}>`}</label>`}
function render(){ $('project').innerHTML=Object.entries({name:'案件名稱',client:'客戶稱呼',phone:'聯絡電話',address:'施工地址',date:'勘查日期'}).map(([k,l])=>field(l,k,data.project[k])).join('');$('conditions').innerHTML=Object.entries({ground:['地面',['一般土壤','混凝土','碎石','岩盤','待確認']],access:['進場條件',['小貨車可達','大貨車可達','僅人力搬運','待確認']],slope:['地形',['平坦','緩坡','階梯落差','待確認']],demolition:['既有圍籬',['不需拆除','需拆除清運','待確認']],boundary:['界址',['已確認','待確認']],utilities:['地下管線',['已確認位置','待確認']]}).map(([k,[l,o]])=>field(l,k,data.conditions[k],o)).join('');$('notes').value=data.notes;
$('segments').innerHTML=data.segments.map((s,i)=>`<div class="segment" data-index="${i}"><div class="between"><b>${String(i+1).padStart(2,'0')} · ${s.type==='gate'?'大門':'菱形網圍籬'}</b><button data-remove="${i}" ${data.segments.length===1?'disabled':''}>移除此段</button></div><div class="grid">${field('類型','type',s.type,[['fence','菱形網圍籬'],['gate','大門']])}${field('柱心長度 m','length',s.length,null,.5,5000)}${field(i?'相對前段轉角 °（左正右負）':'起始方向 °','turn',s.turn,null,-180,180)}${field('高度 m','height',s.height,[1.2,1.5,1.8,2,2.4,3])}${field('最大柱距 m','spacing',s.spacing,[1,1.5,2,2.5,3])}${field('立柱外徑 mm','postDia',s.postDia,[42.7,48.6,60.5,76.3,89.1,101.6])}${field('網線徑 mm','wire',s.wire,[2.6,3,3.4,4,5])}${field('網目','meshChoice',s.meshChoice,[...Object.keys(meshOptions),...(!meshOptions[s.meshChoice]?[s.meshChoice]:[])])}${field('網材質','meshMat',s.meshMat,[['galv','鍍鋅'],['highgalv','高鍍鋅'],['pvc','PVC 包覆（綠）']])}${field('橫桿排數','railCount',s.railCount,[0,1,2,3,4])}${field('基礎工法','base',s.base,[['buried','埋入／混凝土'],['direct','單獨埋入'],['plate','底板固定']])}${field('埋深 cm（50 起）','depth',Number((s.depth*100).toFixed(2)),null,50,200,5)+field('此段怪手需求','excavator',s.excavator,['待確認','需要怪手','不需怪手'])}${s.type==='gate'?field('門型','gate',s.gate,[['single','單開'],['double','雙開']])+field('門開啟角度 °','angle',s.angle,[0,45,90,110]):''}</div><div class="turns"><button type="button" data-turn="90">左轉 90°</button><button type="button" data-turn="0">直行</button><button type="button" data-turn="-90">右轉 90°</button></div><label>此段備註<textarea data-key="note" rows="2">${esc(s.note)}</textarea></label></div>`).join('');
$('pricing').innerHTML=field('雜項／運費／拆除 NT$','extra',data.pricing.extra,null,0,1e7)+field('折讓 NT$','discount',data.pricing.discount,null,0,1e7)+field('稅率 %','tax',data.pricing.tax,[0,5]);update()}
function design(){let heading=0;const nodes=[{x:0,z:0}],edges=[];for(const [i,s]of data.segments.entries()){heading+=s.turn*Math.PI/180;const a=nodes.at(-1);nodes.push({x:a.x+Math.cos(heading)*s.length,z:a.z-Math.sin(heading)*s.length});edges.push({...s,a:i,b:i+1,style:s.type==='gate'?'gate':'clamp',postDia:s.type==='gate'?Math.max(89.1,s.postDia):s.postDia,thickness:2,railShape:'round',railDia:30,material:'galv',basePreset:'15',baseSize:15,topFix:'through',meshColor:'green',direction:1,brace:true,gateType:s.gate})}return{format:'sq-fence-design',version:1,name:data.project.name.slice(0,60),nodes,edges}}
function estimate(){let mesh=0,rail=0,total=0,gates=0;const posts=new Map(),d=design();function add(x,z,s,gate=false){const k=x.toFixed(4)+','+z.toFixed(4);if(!posts.has(k))posts.set(k,{base:s.base,gate});else if(gate)posts.get(k).gate=true}for(const[i,s]of data.segments.entries()){total+=s.length;const a=d.nodes[i],b=d.nodes[i+1];add(a.x,a.z,s,s.type==='gate');add(b.x,b.z,s,s.type==='gate');if(s.type==='gate'){gates++;continue}mesh+=s.length;rail+=s.length*s.railCount;const spans=Math.ceil((s.length-1e-8)/s.spacing);for(let n=1;n<spans;n++)add(a.x+(b.x-a.x)*n/spans,a.z+(b.z-a.z)*n/spans,s)}const plate=[...posts.values()].filter(p=>p.base==='plate').length,direct=[...posts.values()].filter(p=>p.base==='direct').length;return{total,posts:posts.size,mesh,rail,gates,plate,direct,buried:posts.size-plate-direct}}
const names={mesh:['菱形網（按長度）','m'],post:['立柱（含門柱）','支'],rail:['橫桿','m'],plate:['底板固定基礎','處'],buried:['埋入／混凝土基礎','處'],direct:['單獨埋入（請填單價）','處'],gate:['門組（含門片）','組'],labor:['安裝工資','m']};
function lines(){const q=estimate();return Object.entries(names).map(([k,[name,unit]])=>({key:k,name,unit,qty:({post:q.posts,gate:q.gates,labor:q.total})[k]??q[k],rate:data.rates[k]})).concat([{key:'excavatorWork',name:'怪手施工費',unit:'台班',qty:data.pricing.excavatorShifts,rate:data.pricing.excavatorRate,manual:true},{key:'excavatorTransport',name:'怪手進退場費',unit:'式',qty:1,rate:data.pricing.excavatorTransport,manual:true}])}
function quote(){const items=lines(),subtotal=items.reduce((n,l)=>n+l.qty*l.rate,0)+data.pricing.extra,net=Math.max(0,subtotal-data.pricing.discount),tax=Math.round(net*data.pricing.tax/100);return{items,excavatorSubtotal:data.pricing.excavatorShifts*data.pricing.excavatorRate+data.pricing.excavatorTransport,subtotal,net,tax,total:net+tax}}
function money(n){return Math.round(n).toLocaleString('zh-TW')}
function update(){const q=estimate();$('metrics').innerHTML=[['總長（含門）',q.total.toFixed(1),'m'],['菱形網長度',q.mesh.toFixed(1),'m'],['立柱',q.posts,'支'],['大門',q.gates,'組']].map(([l,n,u])=>`<div class="metric">${l}<b>${n}</b>${u}</div>`).join('');$('bill').innerHTML=lines().map(l=>`<tr><td>${l.name}</td><td>${l.qty.toFixed(2)} ${l.unit}</td><td><input aria-label="${l.name}每${l.unit}單價" data-rate="${l.key}" type="number" min="0" max="10000000" value="${l.rate}" ${l.manual?'disabled':''}><small>元／${l.unit}</small></td><td>${money(l.qty*l.rate)}</td></tr>`).join('');$('excavatorPricing').innerHTML=field('預估台班數（可填0.5）','excavatorShifts',data.pricing.excavatorShifts,null,0,1000,.5)+field('每台班單價 NT$','excavatorRate',data.pricing.excavatorRate,null,0,1e7)+field('進退場費合計 NT$','excavatorTransport',data.pricing.excavatorTransport,null,0,1e7);const equipment=quote();const needs=data.segments.filter(s=>s.excavator==='需要怪手').length;$('excavatorSummary').textContent='怪手費用小計 NT$ '+money(equipment.excavatorSubtotal)+'（'+needs+' 段勾選需要怪手）'+(needs&&(data.pricing.excavatorShifts===0||data.pricing.excavatorRate===0)?'；已選需要怪手，請補台班數與單價。':'');const {subtotal,net,tax}=equipment;$('totals').innerHTML=`未稅小計 NT$ ${money(subtotal)}<br>折讓 NT$ ${money(data.pricing.discount)} · 稅額 NT$ ${money(tax)}<br><strong>試算總額 NT$ ${money(net+tax)}</strong>${data.pricing.discount>subtotal?'<p class="warning">折讓超過小計，計稅基礎以 0 計。</p>':''}`;try{localStorage.setItem('sq-field-survey-v1',JSON.stringify(data));$('status').textContent='已自動儲存在本機'}catch{$('status').textContent='無法本機儲存，請匯出備份'}$('applyStatus').textContent=applied?(appliedSource===JSON.stringify(data)?'已套入目前資料':'表單已修改，配置仍保留上次套入內容'):'尚未套入，請完成表單後按下方按鈕'}
function notice(t){$('notice').textContent=t;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',4000)}
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.key,r=el.dataset.rate;if(!k&&!r)return;const prev=structuredClone(data);try{if(el.validity&&!el.validity.valid)throw Error('請輸入欄位範圍內的數值');const box=el.closest('.segment');if(r)data.rates[r]=Number(el.value);else if(box){const s=data.segments[Number(box.dataset.index)];s[k]=k==='depth'?Number(el.value)/100:typeof s[k]==='number'?Number(el.value):el.value}else{const obj=el.closest('#project')?data.project:el.closest('#conditions')?data.conditions:data.pricing;obj[k]=typeof obj[k]==='number'?Number(el.value):el.value}if(k==='meshChoice')data.segments[Number(box.dataset.index)].mesh=meshOptions[el.value]??data.segments[Number(box.dataset.index)].mesh;if(k==='depth'&&Number(el.value)<50)throw Error('埋深至少 50 公分');validate(data);if(k==='type')render();else update()}catch(err){data=prev;render();notice(err.message)}});
$('notes').addEventListener('input',()=>{data.notes=$('notes').value;update()});$('segments').addEventListener('click',e=>{const turn=e.target.closest('[data-turn]');if(turn){const i=Number(turn.closest('.segment').dataset.index);data.segments[i].turn=Number(turn.dataset.turn);render();return}const b=e.target.closest('[data-remove]');if(b&&data.segments.length>1){data.segments.splice(Number(b.dataset.remove),1);render()}});$('add').onclick=()=>{if(data.segments.length>=200)return notice('最多 200 段');data.segments.push(seg());render()};function sendApplied(){if(applied&&studioLoaded)$('studio').contentWindow.postMessage({type:'sq-survey-design',design:applied},location.origin)}
$('studio').onload=()=>{studioLoaded=true;sendApplied()};
$('apply').onclick=()=>{try{validate(data);if(data.segments.some(s=>s.base!=='plate'&&s.depth<.5))throw Error('舊資料含未滿 50 公分的埋深，請先逐段修正');applied=structuredClone(design());appliedSource=JSON.stringify(data);if(!$('studio').getAttribute('src'))$('studio').src='studio.html?embed=1';else sendApplied();$('emptyScene').hidden=true;update();notice('已將填寫完成的表單套入配置')}catch(e){notice(e.message)}};
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('studio').contentWindow&&e.data?.type==='sq-survey-error'){$('status').textContent='圖面超出工具範圍';notice(e.data.message)}});
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('export').onclick=()=>download(JSON.stringify({...data,design:design(),estimate:estimate(),quoteLines:lines(),quoteSummary:quote()},null,2),'上慶勘查資料.json','application/json');$('design').onclick=()=>download(JSON.stringify(design(),null,2),'上慶3D設計.json','application/json');$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>500000)throw Error('檔案過大');data=validate(migrate(JSON.parse(await f.text())));render();notice('已載入勘查資料')}catch(e){notice(e.message)}$('file').value=''};$('csv').onclick=()=>{const rows=[['項目','數量','單位','單價','小計'],...lines().map(l=>[l.name,l.qty,l.unit,l.rate,Math.round(l.qty*l.rate)]),['雜項',1,'式',data.pricing.extra,data.pricing.extra],['折讓',1,'式',-data.pricing.discount,-data.pricing.discount],['稅額',1,'式',quote().tax,quote().tax],['含稅總額','','','',Math.round(quote().total)]];download('\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'上慶材料報價.csv','text/csv;charset=utf-8')};$('print').onclick=()=>window.print();window.survey={design,estimate,quote,validate,migrate,getData:()=>structuredClone(data)};render();

:root{--ink:#173c35;--green:#12694f;--line:#dbe4dc;--muted:#6b7c74}*{box-sizing:border-box}body{margin:0;background:#f2f4ee;color:var(--ink);font:15px 'Microsoft JhengHei',system-ui,sans-serif}header{display:flex;align-items:center;gap:24px;padding:25px 4%;background:#163f34;color:white}header small{letter-spacing:2px;color:#c0d6b5}h1{font-size:23px;margin:5px 0}.logo{font-size:27px;font-weight:800;border-right:1px solid #78988b;padding-right:24px;white-space:nowrap}.logo span{display:block;font-size:13px;letter-spacing:6px}header button:first-of-type{margin-left:auto}button{cursor:pointer;background:white;border:1px solid var(--line);border-radius:8px;padding:11px 14px;color:var(--ink);font:inherit;min-height:44px}button:hover{background:#e4efdf}main{display:grid;grid-template-columns:minmax(360px, .95fr) minmax(440px,1.15fr);gap:28px;max-width:1600px;margin:auto;padding:30px 4%}.intro h2{font-size:29px;margin:12px 0}.intro p,.muted{font-size:13px;line-height:1.8;color:var(--muted)}.tag{font-size:12px;letter-spacing:2px;font-weight:700;color:#4a705b}.card{padding:22px;background:#fff;border:1px solid var(--line);border-radius:14px;margin:18px 0}h3{margin:0 0 15px;font-size:17px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:12px;color:#577065}input,select,textarea{font:inherit;font-size:15px;color:var(--ink);display:block;width:100%;padding:11px;margin-top:6px;border:1px solid #d3dfd3;border-radius:7px;background:#fafcf8;min-height:44px}input:focus,select:focus,textarea:focus{outline:2px solid #7da788}.between{display:flex;align-items:center;justify-content:space-between;gap:10px}.between h3{margin:0}.segment{border-top:1px solid var(--line);padding:20px 0 4px}.segment .between{margin-bottom:15px}.segment b{font-size:16px}.segment textarea{margin-bottom:12px}.scene{height:430px;background:#e6ede2;border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-top:16px}iframe{width:100%;height:100%;border:0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.metric{background:#e4ecdd;padding:14px;border-radius:9px;font-size:11px}.metric b{display:block;font-size:24px;margin:6px 0}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:10px 4px;border-bottom:1px solid var(--line);text-align:left}td input{width:90px;padding:7px;margin:0}th{color:#65816c;font-weight:500}.warning{font-size:12px;background:#fff5dd;padding:12px;line-height:1.7;color:#806229}#totals{padding:20px 0;line-height:2}#totals strong{font-size:27px}summary{cursor:pointer}details p{font-size:13px;line-height:1.8}#status{font-size:12px;color:#537b51}#notice{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#173c35;color:white;border-radius:10px;padding:12px;display:none;z-index:50}@media(max-width:900px){main{grid-template-columns:1fr;padding:20px 14px;gap:10px}header{flex-wrap:wrap;padding:18px;gap:15px}h1{font-size:18px}header button:first-of-type{margin-left:0}.scene{height:330px}.card{padding:17px}.metrics{gap:6px}.metric{padding:10px}.metric b{font-size:21px}}@media print{header button,.form,button,details{display:none}main{display:block}.scene{height:350px}.card{break-inside:avoid}header{color:#173c35;background:white}body{background:white}}

